('h2', "11.6  Teamwork"),
('def', ("Team",
         "A **small group of people with complementary skills**, who are **committed to a common purpose, performance goals and approach**, and who hold themselves **mutually accountable** for the outcome (Katzenbach & Smith).")),
('def', ("Teamwork",
         "The **cooperative and coordinated effort** of the members of a group to achieve a common goal efficiently and effectively, in which individual interests are subordinated to the unity and objectives of the group.")),
